from lib import *
S = SS('v34')
steps = [
    step("证书链要配全。证书由我自己签:根 CA → 中间 CA → 叶子,client 只信任根。nginx 的 ssl_certificate 只放叶子证书:client 校验失败,unable to get local issuer certificate,nginx 只发了 1 张证书。放“叶子 + 中间 CA”(fullchain):握手成功,校验通过,nginx 发了 2 张证书。叶子证书不是根直接签的,client 需要中间 CA 才能一路验证到自己信任的根;服务端不发中间证书时,有的 client 会自己下载(AIA),这里的 Python 不会。", t=tl(S(1)), mark=lidx(S(1), '只有叶子证书'), done=lidx(S(1), 'fullchain'), b=bars([['只有叶子:发出的证书数', 1, '1 张 · 校验失败'], ['fullchain:发出的证书数', 2, '2 张 · 校验通过']], 2, mark=[0], done=[1]), kv=KV([['只有叶子证书', 'unable to get local issuer certificate'], ['叶子 + 中间 CA', '握手成功']], ['只有叶子证书'])),
    step("握手耗时与会话复用。每种配置 200 次全新的 TCP 连接加 TLS 握手,取中位数。ECDSA P-256:TLS 1.2 是 0.78 ms,TLS 1.3 是 0.88 ms。RSA 2048:1.23 ms 和 1.36 ms。RSA 4096:4.25 ms 和 4.14 ms,p99 6.68 ms 和 7.42 ms。密钥类型的影响比 TLS 版本大(本机环回上没有网络往返,TLS 1.3 少一个往返的好处看不出来,TLS 1.3 反而略高几十微秒)。会话复用:ssl_session_cache off 且 ticket 也关:带着上次的会话重连,0 / 100 次被复用,握手中位数 1.35 ms;shared 会话缓存加默认的 session tickets:100 / 100 次被复用,中位数 0.68 ms(RSA 2048)。", t=tl(S(2)), mark=lidx(S(2), 'rsa4096'), done=lidx(S(2), 'ec256', 'rsa2048', 'ssl_session_cache'), b=bars([['ECDSA P-256 TLS 1.3 ms', 0.88, '0.88'], ['RSA 2048 TLS 1.3 ms', 1.36, '1.36'], ['RSA 4096 TLS 1.3 ms', 4.14, '4.14'], ['RSA 2048 会话复用 ms', 0.68, '0.68(没复用 1.35)']], 4.5, done=[0, 1, 3], mark=[2]), kv=KV([['ECDSA P-256', '0.78 ms (1.2) / 0.88 ms (1.3)'], ['RSA 4096', '4.25 ms (1.2) / 4.14 ms (1.3)'], ['会话复用', '100 / 100 被复用,0.68 ms 对 1.35 ms']], ['RSA 4096'])),
    step("到上游是明文还是重新加密,以及上游证书校验。上游有一个 HTTPS 版本,500 个顺序请求的延迟中位数:proxy_pass http://(明文)0.15 ms;proxy_pass https:// 默认 0.15 ms(nginx 1.31.6 默认复用到上游的连接,TLS 握手只做一次);https:// + upstream keepalive 16:0.15 ms;https:// + proxy_ssl_verify on:0.15 ms。强制每个请求新建连接(Connection: close):https 是 1.53 ms(p99 2.93 ms),开启 proxy_ssl_session_reuse 后 0.74 ms,明文 http 是 0.27 ms。重新加密在连接复用时几乎没有额外延迟,新建连接时每次多约 1.3 ms。证书校验:让上游只发叶子证书(没有发中间 CA),默认的 proxy_ssl_verify off 返回 200、没有任何错误;proxy_ssl_verify on 返回 502,error.log 写 upstream SSL certificate verify error: (21:unable to verify the first certificate)。默认的“重新加密”只是加密,不是认证。", t=tl(S(3)), mark=lidx(S(3), 'proxy_ssl_verify on', 'Connection: close(每个'), done=lidx(S(3), 'proxy_pass http://(明文)', 'proxy_pass https://,默认', 'keepalive 16', 'proxy_ssl_verify off'), b=bars([['https 复用连接:中位数 ms', 0.15, '0.15'], ['http + Connection close:中位数 ms', 0.27, '0.27'], ['https + Connection close:中位数 ms', 1.53, '1.53'], ['verify on 遇到不完整证书链', 502, '502(off 时 200)']], 502, done=[0], cur=[1], mark=[2, 3]), kv=KV([['连接复用时', 'http 与 https 都是 0.15 ms'], ['每请求新建连接', 'https 1.53 ms,http 0.27 ms'], ['proxy_ssl_verify 默认 off', '证书链不完整也 200;on 才 502']], ['proxy_ssl_verify 默认 off'])),
]
A = mkartv('v34', 34, '微服务,网关,nginx,TLS,证书链,会话复用,真实验证,动画演示',
    '实测 TLS 终止:证书只放叶子时 client 校验失败、fullchain 才通过;握手 RSA 4096 约 4.1 ms 而 ECDSA P-256 约 0.9 ms;会话复用 100 / 100 把握手从 1.35 ms 降到 0.68 ms;到上游重新加密在连接复用时没有额外延迟,新建连接时约多 1.3 ms;proxy_ssl_verify 默认 off。',
    '网关做 TLS 终止要把证书链配成什么样?RSA 和 ECDSA 的握手差多少?会话复用有多大帮助?到上游是明文还是重新加密,代价和安全性怎么样?这篇用自己签的证书链和 nginx 1.31.6 量出来。',
    [('unable to get local issuer certificate', '只配叶子证书时 client 的校验错误;配成“叶子 + 中间 CA”才通过'), ('4.14 ms 对 0.88 ms', 'RSA 4096 与 ECDSA P-256 叶子证书的 TCP + TLS 1.3 握手耗时中位数'), ('verify off', 'nginx 的 proxy_ssl_verify 默认是 off:上游证书链不完整也照常放行,打开后才返回 502')],
    [('证书链', '<p>叶子证书之外要把中间 CA 一起发出去,client 才能验证到根。</p>'),
     ('握手耗时与会话复用', '<p>密钥类型的影响大于 TLS 版本;会话复用把握手耗时降一半。</p>'),
     ('到上游重新加密与证书校验', '<p>连接被复用时几乎没有额外延迟,新建连接时每次多一次握手;默认不校验上游证书,重新加密不等于认证。</p>')],
    steps,
    [ENV_V + '。证书由 cryptography 50.0.2 自己签发(根 CA 和中间 CA 是 ECDSA P-256,叶子证书 RSA 2048 / RSA 4096 / ECDSA P-256,有效期 30 天,带 SKI / AKI / KeyUsage——Python 3.14 的校验默认要求这些扩展);nginx 是 Homebrew 的 1.31.6;client 是 Python ssl,只信任这个根 CA;HTTPS 上游是 Python http.server 套 ssl;握手在本机环回上测,没有网络往返,所以 TLS 1.3 省一个往返的好处在这里体现不出来',
     '没有验证:OCSP stapling;ALPN 与 HTTP/2 的协商;mTLS(见 Mesh 部分);证书过期与轮换;真实网络(RTT)下 TLS 1.2 与 1.3 的握手差别;TLS 1.3 的 0-RTT;cipher suite 的选择对耗时的影响'],
    'TLS 终止')
